// 把真实路遇个人战投影为有限货物授权；不读取任意外部结果，不从败绩发明数量。
#include "task_cargo_access.hpp"
#include <algorithm>
namespace hanmo::resident {
TaskCargoAccess::TaskCargoAccess(const CommonStore& common,const PersonalState& personal,const PersonalCatalog& catalog,const InteractionState& interaction):common_(common),personal_(personal),catalog_(catalog),interaction_(interaction){}
Outcome<std::optional<TaskCargoBattleSource>> TaskCargoAccess::task_cargo_source(const StableId& id)const{auto* battle=personal_.battles.find(id);if(!battle)return {false,{},common_failure("UnknownCargoBattle",id).error};if(battle->source.kind=="role")return {true,{}, {}};if(battle->source.kind!="encounter"||battle->source.context)return {false,{},common_failure("UnsupportedCargoSource",id,ErrorKind::unsupported_capability).error};const EncounterRecord* encounter=nullptr;for(const auto& row:interaction_.encounters)if(row.id==battle->source.encounter_id){encounter=&row;break;}if(!encounter&&battle->applied&&battle->phase=="closed"){bool possible_policy=false;for(const auto& row:battle->units.rows())if(row.second.side==1){auto* person=common_.state().actors.find(row.first);if(!person){possible_policy=true;break;}auto* authored=catalog_.road_conflicts.find(person->prototype_id.value_or(person->id));if(authored&&authored->cargo_policy){possible_policy=true;break;}}if(!possible_policy)return {true,{}, {}};}if(!encounter||(encounter->leaders[0]!=battle->controller_id&&encounter->leaders[1]!=battle->controller_id))return {false,{},common_failure("CargoEncounterSourceMissing",id).error};const auto side=encounter->leaders[0]==battle->controller_id?0u:1u;const auto opponent=encounter->leaders[1-side];auto* actor=common_.state().actors.find(opponent);auto* controller=common_.actor(battle->controller_id);auto* controller_unit=battle->units.find(battle->controller_id);auto* opponent_unit=battle->units.find(opponent);if(!actor)return {false,{},common_failure("CargoBattleParticipantsMismatch",id).error};const auto prototype=actor->prototype_id.value_or(actor->id);const auto* terms=catalog_.road_conflicts.find(prototype);if(!terms||!terms->cargo_policy)return {true,{}, {}};if(!controller||!controller_unit||!opponent_unit||controller_unit->side!=0||opponent_unit->side!=1||std::find(encounter->participants.begin(),encounter->participants.end(),controller->id)==encounter->participants.end()||std::find(encounter->participants.begin(),encounter->participants.end(),opponent)==encounter->participants.end())return {false,{},common_failure("CargoBattleParticipantsMismatch",id).error};if(battle->battlefield_id!=terms->battlefield_id)return {false,{},common_failure("CargoBattlefieldMismatch",id).error};if(battle->objective_id!=terms->objective_id){const auto* objective=catalog_.objectives.find(battle->objective_id);const bool protected_unit=std::any_of(battle->units.rows().begin(),battle->units.rows().end(),[](const auto& row){return row.second.side==0&&row.second.protected_actor;});if(!objective||objective->kind!="escort"||!protected_unit)return {false,{},common_failure("CargoObjectiveSourceMismatch",id).error};}std::vector<StableId> encounter_people=encounter->participants,battle_people;for(const auto& row:battle->units.rows())battle_people.push_back(row.first);std::sort(encounter_people.begin(),encounter_people.end());std::sort(battle_people.begin(),battle_people.end());if(std::adjacent_find(encounter_people.begin(),encounter_people.end())!=encounter_people.end()||encounter_people!=battle_people)return {false,{},common_failure("CargoBattleParticipantsMismatch",id).error};auto valid=validate_task_cargo_policy(*terms->cargo_policy);if(!valid.ok)return {false,{},valid.error};TaskCargoBattleSource source;source.battle_id=id;source.encounter_id=encounter->id;source.controller_actor_id=controller->id;source.opponent_actor_id=opponent;source.opponent_prototype_id=prototype;source.policy=*terms->cargo_policy;source.controller_anchor=encounter->anchors[side];source.opponent_anchor=encounter->anchors[1-side];source.created_tick=battle->created_tick;source.completed_tick=battle->completed_tick;source.round=battle->round;source.phase=battle->phase;source.outcome=battle->outcome;source.result_id=battle->result_id;source.result_applied=battle->applied;source.opponent_survived=opponent_unit->hp>0&&!opponent_unit->withdrawn_round;if(battle->applied){const auto* fact=personal_.facts.find(id);const auto* header=common_.state().facts.find(id);std::vector<StableId> participants,defeated,withdrawn;for(const auto& row:battle->units.rows()){participants.push_back(row.first);if(row.second.hp==0)defeated.push_back(row.first);if(row.second.withdrawn_round)withdrawn.push_back(row.first);}std::sort(participants.begin(),participants.end());std::sort(defeated.begin(),defeated.end());std::sort(withdrawn.begin(),withdrawn.end());if(!fact||!header||header->kind!="personal_battle"||header->domain!="personal"||fact->battle_id!=id||fact->result_id!=battle->result_id||fact->outcome!=battle->outcome||fact->tick!=battle->completed_tick||fact->source.kind!="encounter"||fact->source.encounter_id!=encounter->id||fact->source.context||fact->participants!=participants||fact->defeated!=defeated||fact->withdrawn.value_or(std::vector<StableId>{})!=withdrawn)return {false,{},common_failure("CargoBattleResultMismatch",id).error};}else if(personal_.facts.find(id)||common_.state().facts.find(id)||battle->phase!="planning"||!battle->result_id.empty()||battle->completed_tick!=-1)return {false,{},common_failure("PrematureCargoBattleResult",id).error};return {true,std::move(source),{}};}
std::vector<StableId> TaskCargoAccess::task_cargo_sources()const{std::vector<StableId> result;for(const auto& row:personal_.battles.rows())if(row.second.source.kind=="encounter"){auto source=task_cargo_source(row.first);if(!source.ok||source.value)result.push_back(row.first);}return result;}
} // 目录无政策的真实路遇没有货损；角色切磋、军事结果和未知来源不能借这个接口处置货物。
